	s := NewManualCommitStrategy()
	point := RewindPoint{
		ID:      checkpointHash.String(),
		Message: "Checkpoint with nested files",
		Date:    time.Now(),
	}

	if err := s.Rewind(context.Background(), io.Discard, io.Discard, point); err != nil {
		t.Fatalf("Rewind() error = %v", err)
	}

